'use strict';
let opStores=[],opSources=[],opRequests=[],opEvents=[],opEvidence=[],opNotes=[],opMail=[],opMembers=[],opRouting={},activeOp=null,opBusy=false;
const opsKinds={cash:'Cash variances',integration:'Failed integrations',refund:'Refunds',bulk:'Bulk orders',change:'Change order tracker'};
const opsPages={store:['Store workspace','Every variance has an owner, evidence and a next step.','DAILY OPERATIONS'],controller:['Controller desk','Investigate exceptions. Verify evidence. Reconcile balances.','EXCEPTION MANAGEMENT'],notifications:['Notifications','Refresh updates, deadlines and escalation notices.','TEAM ACTIVITY'],training:['Training & process maps','A structured route from daily operations to balance-sheet review.','LEARN THE WORKFLOW'],admin:['Administration','Stores, access, sources and delivery readiness.','SYSTEM CONTROLS']};
Object.assign(titles,opsPages);
sections.splice(1,0,['store','Store workspace','grid'],['controller','Controller desk','search']);
sections.push(['notifications','Notifications','flag'],['training','Training & process maps','book'],['admin','Administration','shield']);
function central(){return ['admin','controller','accountant','management'].includes(member?.role)}
function canControl(){return ['admin','controller','accountant'].includes(member?.role)}
function todayZA(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Johannesburg',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function yesterdayZA(){let d=new Date(todayZA()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10)}
function opStoreOptions(v=''){return '<option value="">Select store</option>'+opStores.filter(s=>s.active).map(s=>'<option value="'+esc(s.code)+'" '+(s.code===v?'selected':'')+'>'+esc(s.code+' · '+s.name)+'</option>').join('')}
function selectField(label,id,values,value){return '<label>'+label+'<select id="'+id+'">'+options(values,value)+'</select></label>'}
function opButton(label,action,cls='secondary'){return '<button type="button" class="button '+cls+'" onclick="'+action+'">'+label+'</button>'}
function stepPath(steps){return '<ol class="process-path">'+steps.map((s,i)=>'<li><b>'+String(i+1).padStart(2,'0')+'</b><span>'+esc(s)+'</span></li>').join('')+'</ol>'}
const opFlows={refund:['Store, date & tender','Available overage check','Card / virtual-card match','Statement & controller review','Approve or escalate'],integration:['Fresh source comparison','Exact ref & amount flagged','Store captures + uploads slip','Next-day source verification','Captured failed int'],cash:['09:00 · Sales − Deposita','Store explains by 15:30','AC action on overdue response','17:00 · Unanswered flag','08:00 next day · Report'],bulk:['Products → proforma','Customer pays & uploads proof','Controller confirms bank / card','Store releases stock','POS sale linked · PMT received'],change:['Store submits request','Controller reviews','Approved → dispatched','Receiving store confirms','Evidence & history retained']};
const oldLoad=load;
load=async function(){await oldLoad();if(!member)return;try{
 const data=await Promise.all(['fpg_stores?order=code','fpg_ops_sources?order=trade_date.desc&limit=1000','fpg_requests?order=updated_at.desc&limit=1000','fpg_request_events?order=created_at.desc&limit=3000','fpg_evidence?order=created_at.desc&limit=3000','fpg_notifications?order=created_at.desc&limit=300','fpg_mail_outbox?order=created_at.desc&limit=200'].map(p=>api(p)));
 [opStores,opSources,opRequests,opEvents,opEvidence,opNotes,opMail]=data;
 opRouting=(await api('fpg_settings?id=eq.operations_routing'))[0]?.value||{};
 if(member.role==='admin')opMembers=await api('rpc/fpg_ops_admin',{method:'POST',body:JSON.stringify({p:{action:'members'}})});
 const selected=$('store').value;$('store').innerHTML='<option value="">All authorised stores</option>'+opStores.map(s=>'<option value="'+esc(s.code)+'">'+esc(s.code+' · '+s.name)+'</option>').join('');$('store').value=selected;
 // Original imported snapshots: retain the latest completed observation per transaction identity.
 const existingKeys=new Set(rows.map(r=>[r.store,r.trade_date,r.tender,r.reference].join('|')));for(const s of opSources){if(!existingKeys.has([s.store,s.trade_date,s.tender,s.reference].join('|')))rows.push({...s,global_sales:null,gl_sales:null,net_settlement:null,gl_bank:null,voucher:null,gl_voucher:null,basis_verified:false});}
 const timestamps=new Map(runs.map(r=>[r.id,r.created_at]));const seen=new Set();rows=rows.sort((a,b)=>(timestamps.get(b.run_id)||'').localeCompare(timestamps.get(a.run_id)||'')).filter(r=>{let k=[r.store,r.trade_date,r.tender,r.reference].join('|');if(seen.has(k))return false;seen.add(k);return true});render();
 }catch(e){notify('Operations could not load: '+e.message,true)}};
const oldSignOut=signOut;signOut=async function(){opStores=[];opSources=[];opRequests=[];opEvents=[];opEvidence=[];opNotes=[];opMail=[];opMembers=[];opRouting={};await oldSignOut()};
const oldScoped=scoped;scoped=function(a,date='trade_date'){return oldScoped(a,date).filter(r=>!$('day').value||r[date]===$('day').value)};
const oldRender=render;
render=function(){
 if(!opsPages[page]){oldRender();return}
 document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('pageTitle').textContent=titles[page][0];$('pageSubtitle').textContent=titles[page][1];$('eyebrow').textContent=titles[page][2];$('breadcrumbs').textContent='FPG Finance / '+titles[page][0];$('authButton').textContent=session?'Sign out':'Sign in';$('identity').textContent=member?member.display_name+' · '+member.role:'Private company records';$('connection').textContent=member?'Connected · store access enforced':'Supabase · sign in to work';$('filters').hidden=!['store','controller'].includes(page);
 if(page==='training'){renderTraining();return}if(!member){$('view').innerHTML=locked();return}
 if(page==='admin'){if(member.role!=='admin'){$('view').innerHTML=empty('Administrator access required','Store and role assignments are restricted to the Finance administrator.');return}renderAdmin();return}
 if(page==='notifications'){renderNotifications();return}
 if(page==='controller'&&!central()){$('view').innerHTML=empty('Controller access required','Your store workspace contains your permitted requests and actions.');return}
 renderOperations();
};
const baseOverview=renderOverview;
renderOverview=function(){baseOverview();$('view').insertAdjacentHTML('afterbegin','<div class="ops-hero"><div><span class="eyebrow">REVENUE FPG · OPERATIONS TO BALANCE SHEET</span><h2>Less chasing.<br>More resolving.</h2><p>Stores act on exceptions. Controllers investigate and substantiate. Every action follows one shared record.</p><div class="flex">'+opButton('Open store workspace →',"go('store')",'')+opButton('Controller desk',"go('controller')")+opButton('Training & process maps',"go('training')")+'</div></div><div class="day-plan"><b>YOUR DAILY CONTROL CYCLE · SAST</b><div><strong>09:00</strong><span>Cash refresh queued</span></div><div><strong>10:00</strong><span>Integration refresh queued</span></div><div><strong>15:30</strong><span>Cash responses due</span></div><div><strong>17:00</strong><span>AC & region escalation</span></div><div><strong>08:00</strong><span>Unanswered report · next day</span></div></div></div>'+(!member?'':'<div class="callout">'+opStores.length+' configured stores · '+opRequests.filter(r=>!['Closed','Captured failed int','Received','PMT received'].includes(r.status)).length+' open operational records. Scheduled source refreshes require the company bridge; email dispatch status appears in Administration.</div>'));};
function opSelection(){return scoped(opRequests)}
function renderOperations(){let all=opSelection(),kind=opsKinds[sub]?sub:'all';if(sub==='unanswered')all=all.filter(r=>r.kind==='cash'&&r.details.unanswered_flagged_at&&!r.details.responded_at&&!r.details.ac_responded_at);if(sub==='inspection')all=all.filter(r=>['Controller inspection','Awaiting payment verification','Ready for controller'].includes(r.status)||r.status.startsWith('Escalated')||r.details.escalation_reason);if(kind!=='all')all=all.filter(r=>r.kind===kind);
 const selectedPage=page;let labels=[['all','All actions'],...Object.entries(opsKinds)];if(page==='controller')labels.push(['inspection','First inspection'],['unanswered','Unanswered variances']);
 const closed=['Closed','Captured failed int','Received','PMT received'];
 $('view').innerHTML='<div class="kpis">'+kpi('Open actions',all.filter(r=>!closed.includes(r.status)).length,'Within your selected scope')+kpi('Awaiting source verification',all.filter(r=>/refresh|source|verification/i.test(r.status)).length,'Uploads do not clear differences')+kpi('Escalated / overdue',all.filter(r=>/Immediate|Negligence|Escalated/.test(r.status)).length,'AC and controller attention')+kpi('Verified / complete',all.filter(r=>closed.includes(r.status)).length,'Supported by workflow history')+'</div>'+tabs(labels,selectedPage)+'<div class="ops-actions">'+opButton('+ Refund',"newOp('refund')",'')+opButton('+ Bulk order',"newOp('bulk')")+opButton('+ Change order',"newOp('change')")+opButton('Export '+(sub==='unanswered'?'unanswered variances':'register')+' CSV ↓','exportOps()')+'</div>'+(opsKinds[kind]?stepPath(opFlows[kind]):'')+(sub==='unanswered'?'<div class="callout"><b>First on controller inspection.</b> Historical flags remain in the case history. This queue includes records still missing both store and AC responses. Export includes store, date, amount, AC and trail.</div>':'')+'<div class="panel"><div class="panel-head"><div><h3>'+esc(sub==='inspection'?'Controller investigation / inspection':sub==='unanswered'?'Unanswered variances':opsKinds[kind]||'Operational action register')+'</h3><p>Per store · per day · per tender. All times use South African time.</p></div>'+badge(all.length+' records','neutral')+'</div>'+(all.length?table(['Case','Store / day','Workflow','Tender / reference','Amount','Current step','Open'],all.map(r=>'<tr><td>FPG-'+r.number+'</td><td>'+esc(r.store)+'<br><small>'+r.trade_date+'</small></td><td>'+esc(opsKinds[r.kind])+'</td><td>'+esc(r.tender)+'<br><small>'+esc(r.reference.length>25?'FPG-'+r.number:r.reference)+'</small></td>'+cell(r.amount)+'<td>'+badge(r.status,closed.includes(r.status)?'green':/Immediate|Negligence|Escalated/.test(r.status)?'amber':'neutral')+'</td><td>'+btn('Open record →',"openOp('"+r.id+"')")+'</td></tr>')):empty('No records in this selection','Configure stores and import operational sources to populate exceptions. Refund, bulk and change-order requests can be created for an authorised store.'))+'</div>'+(kind==='integration'?kioskConsol():'')+'<div class="note">Registers show up to 1,000 records and the latest 3,000 history / evidence entries. Narrow the selected period for review. C&C and mPOS use settlement comparison until a different approved source mapping is supplied.</div>';
}
function kioskConsol(){const a=scoped(opSources).filter(s=>s.tender==='Kiosk'),group={};a.forEach(s=>{let k=s.store+'|'+s.trade_date;if(!group[k])group[k]={store:s.store,date:s.trade_date,order:0,sett:0,missing:false};group[k].missing ||=s.orderserve==null||s.settlement==null;group[k].order+=s.orderserve||0;group[k].sett+=s.settlement||0});return '<div class="panel"><div class="panel-head"><h3>Kiosk · Orderserve vs settlement control</h3></div>'+table(['Store','Day','Orderserve','Settlement','Difference','State'],Object.values(group).map(s=>'<tr><td>'+esc(s.store)+'</td><td>'+s.date+'</td>'+cell(s.missing?null:s.order)+cell(s.missing?null:s.sett)+cell(s.missing?null:s.order-s.sett)+'<td>'+badge(s.missing?'Missing source':s.order===s.sett?'Balances':'Money difference',!s.missing&&s.order===s.sett?'green':'amber')+'</td></tr>'))+'</div>'}
function openOp(id){activeOp=opRequests.find(r=>r.id===id);if(activeOp)renderOpDialog()}
function newOp(kind){if(!member){authAction();return}if(!opStores.length){notify('The administrator must configure your store and access first.',true);return}activeOp={kind};$('opsTitle').textContent='New '+opsKinds[kind];$('opsBody').innerHTML=stepPath(opFlows[kind])+'<form id="newOpForm"><div class="two-col"><label>Store<select id="opStore" required>'+opStoreOptions($('store').value||(opStores.filter(s=>s.active).length===1?opStores.find(s=>s.active).code:''))+'</select></label>'+field('Trading / order date','opDate',todayZA(),'date')+selectField('Tender','opTender',kind==='change'?['Cash']:kind==='bulk'?['Bank transfer','Card']:['Card','Kiosk','Mpos','Cash','C&C','Mrd','Uber','Wi-code'],kind==='change'?'Cash':'Card')+field('Submitted by','opSubmitter',member.display_name)+'</div>'+(kind==='bulk'?field('Customer / company','opCustomer','')+field('Customer email (optional)','opEmail','','email')+'<h3>Order items</h3><div id="bulkLines"></div>'+opButton('+ Add product','addBulkLine()')+'<div class="metric-line"><b>Proforma total</b><b id="bulkTotal">R 0.00</b></div><p class="muted">Unit prices include any applicable tax. This is a proforma, not a VAT tax invoice.</p>':field('Amount (ZAR)','opAmount','','number'))+(kind==='refund'?'<label>Reason for refund<textarea id="opReason" required></textarea></label>':kind==='change'?field('Store supplying the change / requested from','opFrom','')+'<label>Denominations / quantities requested<textarea id="opDenominations" required placeholder="e.g. 20 × R10, 10 × R20"></textarea></label><label>Request notes<textarea id="opReason"></textarea></label>':'')+'<p id="opError" class="negative" role="alert"></p><button class="button" id="newOpSubmit">'+(kind==='bulk'?'Generate proforma':'Create request')+' →</button></form>';$('newOpForm').addEventListener('submit',createOp);if(kind==='bulk')addBulkLine();$('opsDialog').showModal()}
function addBulkLine(){const d=document.createElement('div');d.className='bulk-line';d.innerHTML='<label>Product<input class="product" required></label><label>Quantity<input class="qty" type="number" min="1" step="1" value="1" required oninput="bulkTotal()"></label><label>Unit price (ZAR)<input class="unit" type="number" min="0" step="0.01" required oninput="bulkTotal()"></label><button type="button" class="close" aria-label="Remove product" onclick="this.parentElement.remove();bulkTotal()">×</button>';$('bulkLines').appendChild(d)}
function bulkItems(){return [...document.querySelectorAll('.bulk-line')].map(l=>({product:l.querySelector('.product').value.trim(),qty:Number(l.querySelector('.qty').value),unit:cents(l.querySelector('.unit').value)||0}))}
function bulkTotal(){try{$('bulkTotal').textContent=money(sum(bulkItems(),i=>i.qty*i.unit))}catch{$('bulkTotal').textContent='Check unit price'}}
async function createOp(e){e.preventDefault();if(opBusy)return;opBusy=true;$('newOpSubmit').disabled=true;try{let k=activeOp.kind,details={submitted_by:$('opSubmitter').value.trim()},amount;if(k==='bulk'){Object.assign(details,{customer:$('opCustomer').value.trim(),email:$('opEmail').value,items:bulkItems()});if(details.items.some(i=>!i.product||!Number.isInteger(i.qty)||i.qty<=0))throw Error('Enter valid products and whole quantities.');amount=sum(details.items,i=>i.qty*i.unit)}else{amount=cents($('opAmount').value);details.reason=$('opReason')?.value.trim()||''}if(k==='change')Object.assign(details,{requested_from:$('opFrom').value.trim(),denominations:$('opDenominations').value.trim()});if(!validDate($('opDate').value))throw Error('Choose a valid date.');activeOp=await opRPC({action:'create',kind:k,store:$('opStore').value,trade_date:$('opDate').value,tender:$('opTender').value,amount,details});await load();renderOpDialog();notify('Request saved. Evidence and history stay on this record.')}catch(e){$('opError').textContent=e.message}finally{opBusy=false;if($('newOpSubmit'))$('newOpSubmit').disabled=false}}
async function opRPC(p){return api('rpc/fpg_request_action',{method:'POST',body:JSON.stringify({p})})}
function renderOpDialog(){const r=activeOp;if(!r?.id)return;const d=r.details,control=canControl();$('opsTitle').textContent='FPG-'+r.number+' · '+opsKinds[r.kind];let fields='';
 if(r.kind==='refund')fields=field('Processor card / virtual-card fingerprint','opCard',d.card_token||'')+'<p class="muted">Match the processor token and statement. Last four digits alone cannot establish a match. Use redacted customer evidence.</p><div class="flex">'+opButton('Run source checks',"actOp('refund_check')",'')+opButton('No virtual card / still unmatched',"actOp('refund_unmatched')")+(control?opButton('Approve refund',"actOp('refund_approve')"):'')+opButton('Create customer upload link',"customerLink('virtual_card')")+'</div>';
 if(r.kind==='integration')fields='<div class="callout"><b>Capture exactly '+money(r.amount)+' · '+esc(r.reference)+'</b><p>Upload the POS slip, then submit the exact amount and order / reference. The next-day refreshed source must agree before “Captured failed int” appears.</p></div><div class="two-col">'+field('Captured amount (ZAR)','opActionAmount',r.amount/100,'number')+field('Captured reference / order number','opActionRef',r.reference)+'</div>'+opButton('Submit captured failed integration',"actOp('capture')",'')+opButton('Need to capture correct stock',"stockEscalation()")+'<p class="muted">'+(d.capture_reference?'Submitted reference: '+esc(d.capture_reference):'No captured slip submitted yet.')+'</p>';
 if(r.kind==='cash')fields=selectField('Cause','opCause',['GAAP','A.O.D','Deposita','Other'],d.cause)+field('Deposita fault reference (if applicable)','opActionRef',d.fault_reference||'')+'<div class="flex">'+opButton('Submit store explanation',"actOp('cash_response')",'')+(['admin','controller','accountant','ac','regional_ac'].includes(member.role)?opButton('Record AC response & action',"actOp('ac_response')"):'')+'</div>'+(d.explanation?'<div class="callout"><b>Store explanation</b><p>'+esc(d.explanation)+'</p><b>AC action</b><p>'+esc(d.ac_action||'Awaiting AC response')+'</p></div>':'');
 if(r.kind==='bulk')fields='<div class="two-col"><div><b>'+esc(d.customer)+'</b><p class="muted">'+esc(d.email||'')+'</p></div><div>'+opButton('Proforma · Save as PDF',"printProforma()")+'</div></div>'+table(['Product','Qty','Unit price','Line total'],(d.items||[]).map(i=>'<tr><td>'+esc(i.product)+'</td><td>'+i.qty+'</td>'+cell(i.unit)+cell(i.unit*i.qty)+'</tr>'))+'<div class="two-col">'+selectField('Payment method','opMethod',['Bank transfer','Card in store'],d.payment_method)+field('Bank / card / POS reference','opActionRef',d.payment_reference||d.sale_reference||'')+'</div><div class="flex">'+opButton('Submit bulk order payment',"actOp('payment_submit')",'')+opButton('Customer proof-of-payment link',"customerLink('payment')")+(control?opButton('Confirm PMT received in Bank',"actOp('bank_received')")+opButton('Match reviewed card slip to POS',"actOp('card_match')"):'')+opButton('Release to POS / stock',"actOp('bulk_release')")+(control?opButton('Link POS sale · PMT received',"actOp('bulk_link')"):'')+'</div><div class="callout">'+(d.bank_reference?'Bank receipt: '+esc(d.bank_reference):'Stock release is blocked until bank receipt or refreshed card/POS match is verified.')+'<br>Card slip extraction currently requires controller review; automatic OCR is not connected.</div>';
 if(r.kind==='change')fields='<div class="callout"><b>Requested from: '+esc(d.requested_from)+'</b><p>'+esc(d.denominations)+'</p></div><div class="flex">'+(control?['Approved','Rejected','Dispatched'].map(s=>opButton(s,"actOp('change_status',{status:'"+s+"'})")).join(''):'')+opButton('Confirm change received',"actOp('change_status',{status:'Received'})")+'</div><p class="muted">The original Jotform fields have not been supplied. This tracker captures store, supplying store, amount, denominations and the approval trail.</p>';
 const ev=opEvidence.filter(e=>e.request_id===r.id),history=opEvents.filter(e=>e.request_id===r.id).sort((a,b)=>a.created_at.localeCompare(b.created_at));
 $('opsBody').innerHTML=stepPath(opFlows[r.kind])+'<div class="record-summary"><div><b>'+esc(r.store)+' · '+r.trade_date+' · '+esc(r.tender)+'</b><p>'+esc(d.submitted_by||'Source-generated exception')+'</p></div><strong>'+money(r.amount)+'</strong>'+badge(r.status,'neutral')+'</div>'+(d.reason?'<p><b>Reason:</b> '+esc(d.reason)+'</p>':'')+'<div class="callout">'+esc(r.kind==='cash'?'Respond by 15:30 on the next day. AC escalation follows; unanswered at 17:00 appears in the following morning’s report.':r.kind==='integration'?'Capture the prior day’s failed integrations by 17:00. AC and regional AC receive overdue escalation.':'All checks, evidence and decisions remain in this record.')+'</div><div class="two-col"><div><h3>Evidence</h3><label>Document type<select id="opEvidenceType">'+options(['Bank statement','Capture slip','Proof of payment','Card slip','A.O.D','Other'],r.kind==='refund'?'Bank statement':r.kind==='integration'?'Capture slip':r.kind==='bulk'?'Proof of payment':r.kind==='cash'?'A.O.D':'Other')+'</select></label><label>PDF, JPG or PNG · up to 10 MB<input type="file" id="opEvidenceFile" accept="application/pdf,image/jpeg,image/png"></label>'+opButton('Upload evidence','uploadOpEvidence()')+'<ul class="evidence-list">'+ev.map(e=>'<li>'+btn(esc(e.name),"viewOpEvidence('"+e.id+"')")+'<small>'+esc(e.category)+'</small></li>').join('')+'</ul></div><div><h3>Action / investigation notes</h3><label>Explain what happened and the action required<textarea id="opActionNote" placeholder="Required for explanations, approvals and escalation"></textarea></label><p class="muted">'+(control?'Controller review is recorded against your signed-in identity.':'Evidence uploads and comments remain visible to your controller.')+'</p></div></div><h3 class="section-space">Next action</h3>'+fields+'<div class="section-space two-col">'+selectField('Escalation destination','opDestination',control?['controller','bank']:['controller'],'controller')+'<div class="flex">'+opButton('Escalate with process history',"actOp('escalate')")+(control?opButton('Close with conclusion',"actOp('close')"):'')+'</div></div><p id="opError" class="negative" role="alert"></p><div id="customerLinkArea"></div><div class="panel section-space"><div class="panel-head"><h3>Complete process history</h3>'+opButton('Export process CSV ↓','exportOpHistory()')+'</div><ol class="timeline">'+history.map(e=>'<li><small>'+esc(new Date(e.created_at).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'}))+' SAST</small><b>'+esc(e.action)+'</b><p>'+esc(e.note)+'</p></li>').join('')+'</ol></div>';
 if(!$('opsDialog').open)$('opsDialog').showModal();
}
async function actOp(action,extra={}){if(opBusy)return;opBusy=true;document.querySelectorAll('#opsBody button').forEach(b=>b.disabled=true);try{let p={id:activeOp.id,version:activeOp.version,action,note:$('opActionNote')?.value.trim()||'',reference:$('opActionRef')?.value.trim(),amount:$('opActionAmount')?cents($('opActionAmount').value):undefined,card_token:$('opCard')?.value.trim(),cause:$('opCause')?.value,method:$('opMethod')?.value,destination:$('opDestination')?.value,...extra};activeOp=await opRPC(p);await load();renderOpDialog();notify('Saved · '+activeOp.status)}catch(e){$('opError').textContent=e.message}finally{opBusy=false;document.querySelectorAll('#opsBody button').forEach(b=>b.disabled=false)}}
function stockEscalation(){$('opActionNote').value='Need to capture correct stock. Please provide the order breakdown for '+activeOp.reference;$('opDestination').value='controller';actOp('escalate')}
async function storageRequest(path,options={}){if(session.expires_at<Date.now()/1000+60)await refreshSession();let r=await fetch(FPG_CONFIG.url+'/storage/v1/'+path,{...options,headers:{apikey:FPG_CONFIG.key,Authorization:'Bearer '+session.access_token,...options.headers}});if(!r.ok){let d=await r.json();throw Error(d.message||d.error||'Evidence request failed')}return r}
async function uploadOpEvidence(){if(opBusy)return;const file=$('opEvidenceFile').files[0];try{if(!file||!['application/pdf','image/jpeg','image/png'].includes(file.type)||file.size>10485760)throw Error('Choose a PDF, JPG or PNG up to 10 MB.');opBusy=true;let path=activeOp.id+'/'+crypto.randomUUID()+'/'+file.name.replace(/[^a-zA-Z0-9._-]/g,'_');await storageRequest('object/fpg-evidence/'+path,{method:'POST',headers:{'Content-Type':file.type},body:file});await api('rpc/fpg_attach_evidence',{method:'POST',body:JSON.stringify({p:{id:activeOp.id,path,name:file.name,category:$('opEvidenceType').value}})});await load();renderOpDialog();notify('Evidence saved privately. You can now submit the next action.')}catch(e){$('opError').textContent=e.message}finally{opBusy=false}}
async function viewOpEvidence(id){const e=opEvidence.find(e=>e.id===id);let w=window.open('','_blank');try{const r=await storageRequest('object/sign/fpg-evidence/'+e.path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expiresIn:60})}),d=await r.json();const url=FPG_CONFIG.url+'/storage/v1'+(d.signedURL||d.signedUrl);if(w){w.opener=null;w.location=url}else notify('Allow a new tab to view this document.',true)}catch(e){if(w)w.close();notify(e.message,true)}}
async function customerLink(purpose){try{const d=await api('rpc/fpg_customer_link',{method:'POST',body:JSON.stringify({p:{id:activeOp.id,purpose}})});const url=new URL('customer.html',location.href).href.split('#')[0]+'#'+d.token;$('customerLinkArea').innerHTML='<div class="callout"><b>Customer upload link · expires in 48 hours · one submission</b><label>Copy and share with the customer<input readonly id="generatedCustomerLink" value="'+esc(url)+'" onclick="this.select()"></label><p>No customer account required. Only the linked request can receive an upload. A controller verifies the submitted evidence before any approval.</p></div>'}catch(e){$('opError').textContent=e.message}}
function printProforma(){const r=activeOp,d=r.details;let w=window.open('','_blank');if(!w){notify('Allow a new tab to print the proforma.',true);return}w.opener=null;w.document.write('<!doctype html><html><head><title>Proforma FPG-'+r.number+'</title><style>body{font:15px Arial;padding:50px;color:#25313a}h1{font-size:34px}table{width:100%;border-collapse:collapse;margin:40px 0}th,td{text-align:left;padding:14px;border-bottom:1px solid #ddd}.num{text-align:right}small{color:#666}@media print{button{display:none}}</style></head><body><h1>PROFORMA INVOICE</h1><h2>'+esc(opStores.find(s=>s.code===r.store)?.name||r.store)+'</h2><p>Reference: FPG-'+r.number+'<br>Date: '+r.trade_date+'<br>Customer: '+esc(d.customer)+'</p>'+table(['Product','Quantity','Unit price','Total'],d.items.map(i=>'<tr><td>'+esc(i.product)+'</td><td>'+i.qty+'</td>'+cell(i.unit)+cell(i.unit*i.qty)+'</tr>'))+'<h2>Total: '+money(r.amount)+'</h2><p>Prices include applicable tax. This document is not a tax invoice.</p><p>Stock processing starts only after payment verification.</p><button onclick="window.print()">Print / Save as PDF</button></body></html>');w.document.close()}
function exportOps(){let all=opSelection();if(opsKinds[sub])all=all.filter(r=>r.kind===sub);if(sub==='unanswered')all=all.filter(r=>r.kind==='cash'&&r.details.unanswered_flagged_at&&!r.details.responded_at&&!r.details.ac_responded_at);download('FPG-'+(sub||'operations')+'-'+todayZA()+'.csv',csv([['Store','Date','Amount','AC','Trail','Case','Tender','Reference','Status','Region','Explanation','AC Action'],...all.map(r=>{let s=opStores.find(s=>s.code===r.store)||{};return[r.store,r.trade_date,(r.amount/100).toFixed(2),s.ac,s.trail,'FPG-'+r.number,r.tender,r.reference,r.status,s.region,r.details.explanation,r.details.ac_action]})]))}
function exportOpHistory(){download('FPG-'+activeOp.number+'-process.csv',csv([['Case','Time','Action','Note'],...opEvents.filter(e=>e.request_id===activeOp.id).map(e=>['FPG-'+activeOp.number,e.created_at,e.action,e.note])]))}
function renderNotifications(){$('view').innerHTML='<div class="panel"><div class="panel-head"><h3>Team notification centre</h3>'+badge(opNotes.length+' recent','neutral')+'</div>'+(opNotes.length?opNotes.map(n=>'<div class="notification"><div><small>'+esc(new Date(n.created_at).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'}))+' SAST · '+esc(n.store||'All finance')+'</small><h3>'+esc(n.title)+'</h3><p>'+esc(n.body)+'</p></div>'+(n.request_id?btn('View →',"openOp('"+n.request_id+"')"):'')+'</div>').join(''):empty('No notifications yet','Source checks, requests and timed escalations will appear here.'))+'</div>'}
function renderAdmin(){const missing=opStores.filter(s=>!s.ac_email||!s.store_email||!s.regional_email).length;$('view').innerHTML='<div class="kpis">'+kpi('Configured stores',opStores.length,missing+' missing one or more email routes')+kpi('Finance members',opMembers.length,'Store access enforced on the server')+kpi('Operational source rows',opSources.length,'Up to latest 1,000 shown')+kpi('Email queue',opMail.filter(m=>m.status!=='Sent').length,'Queued is not delivered')+'</div><div class="callout"><b>Operational readiness</b><br>Company bridge: must run on an authorised source-access machine. Current imported source: '+esc(opSources[0]?.source_file||'none')+'.<br>Email: delivery requires a configured sender and Resend service key. Every message retains a delivery status.<br>Domain: revenuesystem.sgcnetwork.co.za is attached; DNS / TLS validation was pending at this release.</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Store directory & escalation routing</h3></div><form class="panel-body" id="storeForm"><div class="two-col">'+field('Store code','adminStoreCode','')+field('Store name','adminStoreName','')+field('Area coach (AC)','adminAC','')+field('Regional AC','adminRegionAC','')+field('Region','adminRegion','')+field('Trail / reporting group','adminTrail','')+field('Store email','adminStoreEmail','','email')+field('AC email','adminACEmail','','email')+field('Regional AC email','adminRegionEmail','','email')+'</div><button class="button">Save store</button><p id="storeAdminResult" role="status"></p></form></div><div class="panel"><div class="panel-head"><h3>Finance access</h3></div><form class="panel-body" id="memberForm"><p class="muted">Grant access to an existing SGC account. Store, AC and regional roles see only explicitly assigned store codes.</p>'+field('Account email','adminMemberEmail','','email')+field('Display name','adminMemberName','')+selectField('Role','adminMemberRole',['store','ac','regional_ac','controller','accountant','management','admin'],'store')+field('Store codes (comma separated)','adminMemberStores','')+selectField('Access','adminMemberActive',['Active','Disabled'],'Active')+'<button class="button">Save access</button><p id="memberAdminResult" role="status"></p></form></div></div><div class="panel"><div class="panel-head"><h3>Configured stores</h3></div>'+table(['Store','Name','AC','Region','Trail','Edit'],opStores.map(s=>'<tr><td>'+esc(s.code)+'</td><td>'+esc(s.name)+'</td><td>'+esc(s.ac)+'</td><td>'+esc(s.region)+'</td><td>'+esc(s.trail)+'</td><td>'+btn('Edit',"editStore('"+s.code.replace(/[^A-Za-z0-9_-]/g,'')+"')")+'</td></tr>'))+'</div><div class="panel"><div class="panel-head"><h3>Finance membership register</h3></div>'+table(['Account','Name','Role','Assigned stores','Access'],opMembers.map(m=>'<tr><td>'+esc(m.email)+'</td><td>'+esc(m.display_name)+'</td><td>'+esc(m.role)+'</td><td>'+esc(m.stores.join(', ')||'Finance-wide')+'</td><td>'+badge(m.active?'Active':'Disabled',m.active?'green':'amber')+'</td></tr>'))+'</div><div class="panel"><div class="panel-head"><h3>Operational sources & controlled refresh</h3></div><div class="panel-body"><p>CSV amounts use ZAR with two decimal places. Source identities are store + day + tender + reference. A repeated identity updates that observation; source filenames and import timestamps are retained.</p><div class="flex">'+opButton('Operational CSV template ↓','opsTemplate()')+opButton('Sales / GL / TB imports',"go('reports')")+'</div><label>Operational source CSV<input type="file" id="opsSourceCSV" accept=".csv,text/csv"></label>'+opButton('Validate & import operational source','importOpsCSV()','')+'<p id="opsImportResult" role="status"></p><div class="two-col">'+field('Trade date to reconcile','syncDate',yesterdayZA(),'date')+'<div class="flex">'+opButton('Generate / verify exceptions','syncOps()')+'</div></div><p class="muted">MRD / Uber / C&C / mPOS: settlement − sales. Kiosk: Orderserve − sales; separate Orderserve vs settlement control. Cash: sales − Deposita. Missing source amounts are never treated as zero. The current source adapter must provide captured amount and capture reference to verify a failed integration.</p></div></div><div class="panel"><div class="panel-head"><h3>Email routing & delivery</h3></div><form class="panel-body" id="routeForm"><div class="two-col">'+field('Controller mailbox / copy address','routeController',opRouting.controller||'','email')+field('Bank escalation mailbox','routeBank',opRouting.bank||'','email')+field('Verified sender address','routeFrom',opRouting.from||'','email')+field('HOD emails (comma separated)','routeHods',(opRouting.hods||[]).join(', '))+'</div><button class="button">Save email routing</button><p id="routeResult" role="status"></p></form><div class="panel-body">'+opButton('Check email service readiness','checkEmailReadiness()')+opButton('Dispatch pending workflow emails','dispatchEmails()')+'<p id="emailReadiness" role="status"></p></div>'+table(['Recipient','Subject','Delivery state','Sent at','Error'],opMail.map(m=>'<tr><td>'+esc(m.recipient)+'</td><td>'+esc(m.subject)+'</td><td>'+badge(m.status,m.status==='Sent'?'green':'amber')+'</td><td>'+esc(m.sent_at||'—')+'</td><td>'+esc(m.error||'')+'</td></tr>'))+'</div>';
 $('storeForm').addEventListener('submit',async e=>{e.preventDefault();await adminSave({action:'store',code:$('adminStoreCode').value.trim().toUpperCase(),name:$('adminStoreName').value.trim(),ac:$('adminAC').value,regional_ac:$('adminRegionAC').value,region:$('adminRegion').value,trail:$('adminTrail').value,store_email:$('adminStoreEmail').value,ac_email:$('adminACEmail').value,regional_email:$('adminRegionEmail').value},'storeAdminResult')});
 $('memberForm').addEventListener('submit',async e=>{e.preventDefault();await adminSave({action:'member',email:$('adminMemberEmail').value,display_name:$('adminMemberName').value,role:$('adminMemberRole').value,stores:$('adminMemberStores').value.split(',').map(s=>s.trim().toUpperCase()).filter(Boolean),active:$('adminMemberActive').value==='Active'},'memberAdminResult')});
 $('routeForm').addEventListener('submit',async e=>{e.preventDefault();await adminSave({action:'routing',value:{controller:$('routeController').value,bank:$('routeBank').value,from:$('routeFrom').value,hods:$('routeHods').value.split(',').map(s=>s.trim()).filter(Boolean)}},'routeResult')});
}
async function adminSave(p,id){try{if(p.action==='store'&&(!/^[A-Z0-9_-]{1,30}$/.test(p.code)||!p.name))throw Error('Use a store code with letters, numbers, dash or underscore, and enter its name.');await api('rpc/fpg_ops_admin',{method:'POST',body:JSON.stringify({p})});await load();notify('Saved to the shared system.')}catch(e){$(id).textContent=e.message}}
function editStore(code){let s=opStores.find(s=>s.code===code);if(!s)return;for(let [id,key] of Object.entries({adminStoreCode:'code',adminStoreName:'name',adminAC:'ac',adminRegionAC:'regional_ac',adminRegion:'region',adminTrail:'trail',adminStoreEmail:'store_email',adminACEmail:'ac_email',adminRegionEmail:'regional_email'}))$(id).value=s[key]||'';$('storeForm').scrollIntoView({behavior:'smooth'})}
const opsHeaders=['store','trade_date','tender','reference','sales','settlement','orderserve','captured_amount','capture_reference','card_token','card_last4'];
function opsTemplate(){download('FPG-operational-sources-template.csv',csv([opsHeaders]))}
function validateOpsCSV(text){let raw=parseCSV(text),headers=raw.shift();if(!opsHeaders.every(h=>headers?.includes(h)))throw Error('Use the downloaded operational CSV headings.');if(!raw.length||raw.length>1000)throw Error('Import 1–1,000 rows per batch.');const seen=new Set();return raw.map((r,i)=>{let o=Object.fromEntries(headers.map((h,n)=>[h,(r[n]||'').trim()]));o.store=o.store.toUpperCase();if(!opStores.some(s=>s.code===o.store))throw Error('Unknown store on row '+(i+2));if(!validDate(o.trade_date)||!o.reference)throw Error('Date and reference required on row '+(i+2));o.tender=normalTender(o.tender);for(let k of ['sales','settlement','orderserve','captured_amount'])o[k]=cents(o[k]);if(o.card_last4&&!/^\d{4}$/.test(o.card_last4))throw Error('Card last four digits invalid on row '+(i+2));if(/\d{12,19}/.test(o.card_token))throw Error('Use processor fingerprints, never full card numbers.');let key=[o.store,o.trade_date,o.tender,o.reference].join('|');if(seen.has(key))throw Error('Duplicate source identity on row '+(i+2));seen.add(key);return o})}
async function importOpsCSV(){const status=$('opsImportResult');if(opBusy)return;opBusy=true;try{let f=$('opsSourceCSV').files[0];if(!f||f.size>2097152)throw Error('Choose a CSV up to 2 MB.');let rows=validateOpsCSV(await f.text());status.textContent='Importing…';await api('rpc/fpg_import_ops',{method:'POST',body:JSON.stringify({p:{filename:f.name,rows}})});await load();notify('Imported '+rows.length+' operational rows. Generate / verify exceptions for the relevant day.')}catch(e){status.textContent=e.message}finally{opBusy=false}}
async function syncOps(){try{let date=$('syncDate').value;if(!validDate(date))throw Error('Choose a valid trading date.');await api('rpc/fpg_sync_ops',{method:'POST',body:JSON.stringify({p_date:date})});await load();notify('Source checks completed. Open Store workspace or Controller desk.')}catch(e){notify(e.message,true)}}
async function edgeOps(p){if(session.expires_at<Date.now()/1000+60)await refreshSession();let r=await fetch(FPG_CONFIG.url+'/functions/v1/fpg-operations',{method:'POST',headers:{'Content-Type':'application/json',apikey:FPG_CONFIG.key,Authorization:'Bearer '+session.access_token},body:JSON.stringify(p)}),d=await r.json();if(!r.ok)throw Error(d.error||'Service request failed');return d}
async function checkEmailReadiness(){try{let d=await edgeOps({action:'email_readiness'});$('emailReadiness').textContent=d.ready?'Email service is configured. Pending workflow emails can be dispatched.':d.reason}catch(e){$('emailReadiness').textContent=e.message}}
async function dispatchEmails(){if(opBusy)return;opBusy=true;try{let d=await edgeOps({action:'dispatch'});await load();notify(d.sent+' sent · '+d.failed+' failed. Delivery results are recorded in the outbox.')}catch(e){$('emailReadiness').textContent=e.message}finally{opBusy=false}}
const lessons=[
 {title:'1. Understand the two reconciliation layers',owner:'All users · Day 1',kind:null,body:'Daily operational reconciliation compares sales and receipt sources by store, day, tender and reference. It identifies what the store must correct. Balance-sheet reconciliation proves a GL account’s closing balance using opening balances, movements, the trial balance and a supported outstanding-item schedule. Completing one layer does not complete the other.',check:'Explain one sales-to-settlement variance and one GL-to-TB difference using their separate source records.'},
 {title:'2. Act on store exceptions',owner:'Stores & ACs · Days 1–2',kind:'integration',body:'At 10:00, refresh jobs are queued for the source bridge. Review MRD / Uber settlements and Kiosk Orderserve differences after the data arrives. Capture the exact amount with the exact reference or order number. Upload the POS capture slip. The record stays “Awaiting next refresh” until fresh source data verifies the capture. Request “Need to capture correct stock” when an order breakdown is required.',check:'Practise one capture with its correct reference, amount and slip. Confirm that the upload does not immediately clear the variance.'},
 {title:'3. Explain cash and meet deadlines',owner:'Stores & ACs · Days 2–3',kind:'cash',body:'Use sales minus Deposita for the prior day. Explain the cause and what action will correct it. A GAAP explanation must describe the actual issue; Deposita faults need a fault reference; A.O.D requires linked evidence. Store responses are due at 15:30. The AC must act on overdue cases. At 17:00, cases with no store or AC response are flagged. The next day’s 08:00 unanswered report gives controllers their first inspection queue.',check:'Write a cause, evidence reference, owner and next action for one cash variance. Review the AC response separately.'},
 {title:'4. Refunds, evidence and escalation',owner:'Stores & controllers · Days 3–4',kind:'refund',body:'Select the store, trading day, tender and refund amount. Zero overage returns “Recheck date or tender”. Matching requires the processor card / virtual-card fingerprint and supporting bank statement; last four digits alone are not proof. A customer upload link collects redacted evidence without opening other records. Unmatched cases require investigation, closure with a conclusion, or controller-reviewed bank escalation. A successful check does not transfer money; a controller records approval.',check:'Test a zero-overage rejection, an unmatched card case, and a supported controller review. Read the complete process history.'},
 {title:'5. Bulk orders and change orders',owner:'Stores & controllers · Days 4–5',kind:'bulk',body:'Build a bulk order from products, whole quantities and unit prices. Save the generated proforma as PDF. Upload proof of payment or share a customer upload link. A controller must check actual bank receipt before the store releases stock. For card payments, review the slip and match the refreshed POS date, amount and reference. Link the eventual POS sale to the bulk payment. Change orders follow submission, controller approval, dispatch and receiving-store confirmation.',check:'Generate a proforma and show why a proof-of-payment upload alone cannot release the order.'},
 {title:'6. Substantiate a balance sheet and review independently',owner:'Controllers & independent reviewers · Week 2',kind:null,body:'Work one account and period at a time. Verify opening balance plus debits minus credits equals closing balance; agree that closing balance to the trial balance. Explain each remaining item by reference, store, age, evidence, owner and due date. Prepare an evidenced correction with the correct debit and credit accounts. A different authorised user reviews it before it enters a balanced weekly journal batch. Record the posting reference, refresh the ledger and confirm a zero residual. Do not sign off a period from a partial source extract.',check:'Prepare one account workpaper, one supported outstanding item and one correction for independent review. Demonstrate the post-journal ledger re-check.'}
];
function renderTraining(){let done={};try{done=JSON.parse(localStorage.getItem('fpg_training_'+(session?.user?.id||'guest'))||'{}')}catch{};$('view').innerHTML='<div class="training-intro"><h2>A repeatable routine, with time to investigate.</h2><p>Start with a supervised example, repeat it with a reviewer, then work independently. Use exceptions to decide where effort is needed. Keep operational work and balance-sheet proof as separate queues.</p>'+badge(Object.keys(done).filter(k=>done[k]).length+' / '+lessons.length+' reading checkpoints','green')+'<p class="muted">Reading checkpoints are saved in this browser. Competency and access approval remain with your supervisor.</p></div><div class="learning-grid">'+lessons.map((l,i)=>'<article class="panel lesson"><small>'+esc(l.owner)+'</small><h3>'+esc(l.title)+'</h3><p>'+esc(l.body)+'</p>'+(l.kind?stepPath(opFlows[l.kind]):'')+'<div class="callout"><b>Supervised practice</b><p>'+esc(l.check)+'</p></div><label class="check-label"><input type="checkbox" '+(done[i]?'checked':'')+' onchange="markTraining('+i+',this.checked)"> I have read this and am ready for supervised practice</label>'+(l.kind?opButton('Open '+opsKinds[l.kind],"go('store','"+l.kind+"')"):opButton(i===5?'Open balance-sheet workspace':'Open daily recon',i===5?"go('accounting')":"go('treasury')"))+'</article>').join('')+'</div>'}
function markTraining(i,value){let key='fpg_training_'+(session?.user?.id||'guest'),d={};try{d=JSON.parse(localStorage.getItem(key)||'{}')}catch{};d[i]=value;localStorage.setItem(key,JSON.stringify(d));renderTraining()}
const oldTreasury=renderTreasury;
renderTreasury=function(){if(sub!=='consol'){oldTreasury();$('view').insertAdjacentHTML('afterbegin',opButton('Consol · tender split / all together',"go('treasury','consol')")+'<br><br>');return}let a=scoped(rows),group={};for(let r of a){let k=r.store+'|'+r.trade_date+'|'+r.tender;group[k]??={store:r.store,date:r.trade_date,tender:r.tender,sales:0,settlement:0,missing:false,count:0};let g=group[k];g.sales+=r.sales||0;g.settlement+=r.settlement||0;g.missing||=r.sales==null||r.settlement==null;g.count++}let g=Object.values(group);$('view').innerHTML=tabs([['daily','Daily recon'],['transactions','Transactions'],['consol','Consol']],'treasury')+'<div class="callout">Use Tender = All tenders for the full consol, or select one tender to split the view. Card and manual card share one tender. Missing amounts stay unverified.</div><div class="kpis">'+kpi('Source rows',a.length,'Latest imported observation per reference')+kpi('Sales',money(sum(a,r=>r.sales)),'Available source values')+kpi('Settlement',money(sum(a,r=>r.settlement)),'Available source values')+kpi('Net difference',money(sum(a,r=>delta(r.settlement,r.sales))),'Only comparable pairs')+'</div><div class="panel">'+table(['Store','Day','Tender','Transactions','Sales','Settlement','Difference'],g.map(r=>'<tr><td>'+esc(r.store)+'</td><td>'+r.date+'</td><td>'+r.tender+'</td><td>'+r.count+'</td>'+cell(r.missing?null:r.sales)+cell(r.missing?null:r.settlement)+cell(r.missing?null:r.settlement-r.sales)+'</tr>'))+'</div>'};
