let workpapers=[],workpaperEvents=[],activeWorkpaper=null;
const preWorkpaperLoad=load;load=async function(){await preWorkpaperLoad();if(!member||!central())return;try{[workpapers,workpaperEvents]=await Promise.all([api('fpg_workpapers?order=period.desc&limit=1000'),api('fpg_workpaper_events?order=created_at.desc&limit=3000')]);render()}catch(e){notify('Workpapers could not load: '+e.message,true)}};
const originalAccounting=renderAccounting;renderAccounting=function(){if(!['review','workpapers'].includes(sub)){originalAccounting();$('view').insertAdjacentHTML('afterbegin',opButton('Balance-sheet workpapers & independent review',"go('accounting','workpapers')")+'<br><br>');return}const a=scoped(balances,'period');$('view').innerHTML=tabs([['balance','GL balances'],['tb','Trial balance'],['outstanding','Outstanding items'],['workpapers','Account workpapers'],['review','Period review']],'accounting')+'<div class="callout"><b>Controller preparation → independent review.</b> Substantiate each imported account and store balance. Review requires a verified GL roll-forward, agreement to TB, a support balance and an evidenced outstanding-item schedule. “Reviewed” applies to this workpaper and imported source, not an assurance that every company account or period is complete.</div><div class="panel"><div class="panel-head"><h3>Balance-sheet substantiation register</h3></div>'+(a.length?table(['Period','Store','Account','TB balance','Support + items','Residual','State','Prepare / review'],a.map(b=>{let w=workpapers.find(w=>w.balance_id===b.id),total=w?w.support_balance+sum(w.items,i=>i.amount):null;return '<tr><td>'+b.period+'</td><td>'+esc(b.store)+'</td><td>'+esc(b.account)+'</td>'+cell(b.tb_closing)+cell(total)+cell(delta(b.tb_closing,total))+'<td>'+badge(w?.state||'Not prepared',w?.state==='Reviewed'?'green':'neutral')+'</td><td>'+btn('Open →',"openWorkpaper('"+b.id+"')")+'</td></tr>'})):empty('No imported GL balances','Import the GL / TB template from Reports & sources to start a workpaper.'))+'</div>'};
function openWorkpaper(balanceId){let b=balances.find(b=>b.id===balanceId),w=workpapers.find(w=>w.balance_id===balanceId)||{balance_id:balanceId,items:[],version:0,state:'Draft'};activeWorkpaper=w;let locked=['Pending review','Reviewed'].includes(w.state)||!canControl();$('opsTitle').textContent='Balance-sheet workpaper · '+b.store+' · '+b.account;$('opsBody').innerHTML='<div class="record-summary"><div><b>'+b.period+' · '+esc(b.store)+' · '+esc(b.account)+'</b><p>Imported GL / TB source</p></div><strong>'+money(b.tb_closing)+'</strong>'+badge(w.state)+'</div>'+stepPath(['Verified GL & TB','Support balance','Outstanding items','Controller conclusion','Independent review'])+'<fieldset '+(locked?'disabled':'')+'>'+field('Support schedule balance (ZAR)','wpSupport',w.support_balance==null?'':w.support_balance/100,'number')+'<label>Supporting source references / evidence<textarea id="wpEvidence">'+esc(w.evidence||'')+'</textarea></label><label>Source completeness checks performed<textarea id="wpCompleteness">'+esc(w.completeness_note||'')+'</textarea></label><h3>Outstanding items · signed amounts</h3><p class="muted">Support balance + outstanding items must equal the TB closing balance. Give each item a source reference, owner, evidence and due date.</p><div id="wpItems"></div>'+opButton('+ Add outstanding item','addWorkpaperItem()')+'<label class="section-space">Controller conclusion<textarea id="wpConclusion">'+esc(w.conclusion||'')+'</textarea></label></fieldset><div class="flex">'+(!locked?opButton('Save draft',"saveWorkpaper('Draft')")+opButton('Submit for independent review',"saveWorkpaper('Pending review')",''):'')+'</div>'+(w.state==='Pending review'&&canControl()?'<div class="callout">'+(member.full_process?'Your account can prepare and review this workpaper. This will be recorded as an administrator review.':'The reviewer must be a different authorised user from the preparer.')+'</div><label>Independent review conclusion<textarea id="wpReview"></textarea></label><div class="flex">'+opButton('Review & accept workpaper',"saveWorkpaper('Reviewed')",'')+opButton('Return for correction',"saveWorkpaper('Returned')")+'</div>':'')+'<p id="opError" role="alert" class="negative"></p><div class="section-space">'+opButton('Export workpaper CSV ↓','exportWorkpaper()')+'</div><ol class="timeline">'+workpaperEvents.filter(e=>e.workpaper_id===w.id).map(e=>'<li><small>'+esc(e.created_at)+'</small><b>'+esc(e.state)+'</b><p>'+esc(e.note)+'</p></li>').join('')+'</ol>';w.items.forEach(addWorkpaperItem);if(!$('opsDialog').open)$('opsDialog').showModal()}
function addWorkpaperItem(x={}){let d=document.createElement('div');d.className='wp-item';d.innerHTML='<div class="two-col"><label>Reference<input class="wp-ref" value="'+esc(x.reference||'')+'"></label><label>Signed amount (ZAR)<input class="wp-amount" type="number" step="0.01" value="'+(x.amount==null?'':x.amount/100)+'"></label><label>Owner<input class="wp-owner" value="'+esc(x.owner||'')+'"></label><label>Due date<input class="wp-due" type="date" value="'+esc(x.due_date||'')+'"></label></div><label>Evidence reference<input class="wp-evidence" value="'+esc(x.evidence||'')+'"></label><button type="button" class="text-button" onclick="this.closest(\'.wp-item\').remove()">Remove item</button>';$('wpItems').appendChild(d)}
async function saveWorkpaper(state){if(opBusy)return;opBusy=true;try{let p={...activeWorkpaper,state,review_note:$('wpReview')?.value};if(['Draft','Pending review'].includes(state))Object.assign(p,{support_balance:cents($('wpSupport').value),evidence:$('wpEvidence').value,completeness_note:$('wpCompleteness').value,conclusion:$('wpConclusion').value,items:[...document.querySelectorAll('.wp-item')].map(l=>({reference:l.querySelector('.wp-ref').value,amount:cents(l.querySelector('.wp-amount').value),owner:l.querySelector('.wp-owner').value,due_date:l.querySelector('.wp-due').value,evidence:l.querySelector('.wp-evidence').value}))});const w=await api('rpc/fpg_save_workpaper',{method:'POST',body:JSON.stringify({p})});await load();openWorkpaper(w.balance_id);notify('Workpaper saved · '+w.state)}catch(e){$('opError').textContent=e.message}finally{opBusy=false}}
function exportWorkpaper(){let w=activeWorkpaper,b=balances.find(b=>b.id===w.balance_id);download('FPG-workpaper-'+b.store+'-'+b.account+'-'+b.period+'.csv',csv([['Store','Account','Period','TB','Support balance','State','Evidence','Completeness','Conclusion'],[b.store,b.account,b.period,b.tb_closing/100,w.support_balance==null?'':w.support_balance/100,w.state,w.evidence,w.completeness_note,w.conclusion],[],['Reference','Amount','Owner','Due date','Evidence'],...w.items.map(i=>[i.reference,i.amount/100,i.owner,i.due_date,i.evidence])]))}

let workflowMode='Administrator';
function setWorkflowMode(mode){workflowMode=mode;const destination={Store:'store',Controller:'controller',Accountant:'accounting',Administrator:'admin'}[mode]||'overview';go(destination)}
function updateWorkflowSwitch(){
 let host=document.getElementById('workflowSwitcher');
 if(!member?.full_process){if(host)host.remove();return}
 if(!host){host=document.createElement('label');host.id='workflowSwitcher';host.style.cssText='display:flex;gap:8px;align-items:center;margin:0;font-size:11px';host.innerHTML='<span>Workspace</span><select aria-label="Working workspace" id="workflowModeSelect"><option>Administrator</option><option>Store</option><option>Controller</option><option>Accountant</option></select>';document.querySelector('.header-actions').prepend(host);document.getElementById('workflowModeSelect').addEventListener('change',e=>setWorkflowMode(e.target.value))}
 document.getElementById('workflowModeSelect').value=workflowMode;
 document.getElementById('identity').textContent=member.display_name+' · Full access';
}
const renderWithFullAccess=render;render=function(){renderWithFullAccess();updateWorkflowSwitch()};
render();
